const body = $input.first().json.body || {};
const businessName = (body.businessName || '').toString().trim();
const systemPrompt = (body.systemPrompt || '').toString().trim();

if (!systemPrompt) {
  throw new Error('systemPrompt is required');
}

// Assistant to update (the pipeline demo bot that works over the phone)
const assistantId = (body.assistantId || 'c428c7f1-65bc-4207-8728-f08a214f2361').toString().trim();

// Prepend the business name as context if provided
const finalPrompt = businessName
  ? `You are the AI phone receptionist for ${businessName}.\n\n${systemPrompt}`
  : systemPrompt;

return [{
  json: {
    assistantId,
    systemPrompt: finalPrompt
  }
}];

const res = $input.first().json;

if (res && res.error) {
  const details = (res.error && (res.error.message || res.error.description)) || res.error || 'Unknown error';
  return [{ json: { success: false, error: 'Could not update assistant', details: details.toString() } }];
}

const data = (res && res.data) || res || {};
const ok = res && (res.success === true || data.id);

if (!ok) {
  return [{ json: { success: false, error: 'Could not update assistant', details: (res && res.message) || 'Unexpected response' } }];
}

return [{
  json: {
    success: true,
    message: 'Assistant updated successfully',
    assistantId: data.id || null,
    name: data.name || null
  }
}];
